import java.util.*;

class Solution {
    public long getMinOperations(int[] weight, int[] dist) {
        int n = weight.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(weight[a], weight[b]));
        long[] pos = new long[n];
        for (int i = 0; i < n; i++) pos[i] = i;
        long ops = 0;
        long last = -1;
        for (int idx : order) {
            if (pos[idx] > last) { last = pos[idx]; continue; }
            long need = last + 1 - pos[idx];
            long k = (need + dist[idx] - 1) / dist[idx];
            ops += k;
            pos[idx] += k * dist[idx];
            last = pos[idx];
        }
        return ops;
    }
}

#include <vector>
#include <algorithm>
#include <numeric>
using namespace std;

class Solution {
public:
    long long getMinOperations(vector<int>& weight, vector<int>& dist) {
        int n = weight.size();
        vector<int> order(n);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b){ return weight[a] < weight[b]; });
        vector<long long> pos(n);
        for (int i = 0; i < n; i++) pos[i] = i;
        long long ops = 0, last = -1;
        for (int idx : order) {
            if (pos[idx] > last) { last = pos[idx]; continue; }
            long long need = last + 1 - pos[idx];
            long long k = (need + dist[idx] - 1) / dist[idx];
            ops += k;
            pos[idx] += k * (long long) dist[idx];
            last = pos[idx];
        }
        return ops;
    }
};
